from decimal import Decimal,ROUND_HALF_UP
R=os.path.expanduser("~/bones-forge/rank_index/public/college/cds/")
def acc(a,d):
    v=Decimal(d)*100/Decimal(a)
    return float(v.quantize(Decimal("0.1"),ROUND_HALF_UP)),int(v.quantize(Decimal("1"),ROUND_HALF_UP))
def yr(src,loc,b1,b1n,c1,c9,i2,sec,grad,ret,notes):
    a,d,e=c1; p1,pw=acc(a,d)
    s=sec; keys=["2-9","10-19","20-29","30-39","40-49","50-99","100+"]
    I3=dict(zip(keys,s[:7])); I3["total"]=s[7]; assert sum(s[:7])==s[7]
    I3["pct_under_20_1dp"]=float((Decimal(s[0]+s[1])*100/Decimal(s[7])).quantize(Decimal("0.1"),ROUND_HALF_UP))
    coh,b6,b7,b9,b10,pell=grad
    g={"cohort":coh,"B6_adj_cohort":b6,"B7_4yr":b7,"B9_6yr":b9,"B10_6yr_rate_printed":b10,"rate_4yr_1dp":float((Decimal(b7)*100/Decimal(b6)).quantize(Decimal("0.1"),ROUND_HALF_UP)),"pell_6yr_rate":pell}
    return {"exists":True,"source_url":src,"local_file":loc,"date_read":"2026-11-10",
     "B1_total_undergrad":{"value":b1,"item":"B1","note":b1n},
     "C1":{"applicants":a,"admits":d,"enrolled":e,"acceptance_pct_1dp":p1,"acceptance_pct_whole":pw},
     "C9":c9,"I2_ratio":i2,"I3":I3,"B_grad":g,"B22_retention":ret,"notes":notes}
